function queueDigestConfig(input, nowIso) {
  const config = { ...input }
  if (!/^\d+$/.test(String(config.projectId)) || Number(config.projectId) < 1)
    throw new Error('Select your AppStruct projectId before running the live review.')
  if (typeof config.tableName !== 'string' || !config.tableName.trim())
    throw new Error('Select your AppStruct tableName before running the live review.')
  if (!Number.isInteger(config.limit) || config.limit < 2 || config.limit > 2000)
    throw new Error('Use a row limit between 2 and 2000; a result at the limit stops the review.')
  for (const field of ['id', 'request', 'status', 'owner', 'dueDate'])
    if (typeof config.fields?.[field] !== 'string' || !config.fields[field].trim())
      throw new Error(`Map fields.${field} to the corresponding source column.`)
  if (typeof config.notify !== 'boolean') throw new Error('notify must be true or false.')
  if (config.notify)
    for (const field of ['fromEmail', 'toEmail'])
      if (!/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(config[field] || ''))
        throw new Error(`Set one valid ${field} address before enabling notifications.`)
  if (typeof config.timezone !== 'string' || !config.timezone.trim())
    throw new Error('Set an explicit IANA timezone, for example UTC or Europe/London.')
  const date = new Date(nowIso)
  if (!Number.isFinite(date.getTime())) throw new Error('A valid execution time is required.')
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone: config.timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    })
      .formatToParts(date)
      .map(({ type, value }) => [type, value])
  )
  config.referenceDate = config.referenceDateOverride || `${parts.year}-${parts.month}-${parts.day}`
  const parsed = new Date(`${config.referenceDate}T00:00:00.000Z`)
  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(config.referenceDate) ||
    !Number.isFinite(parsed.getTime()) ||
    parsed.toISOString().slice(0, 10) !== config.referenceDate
  )
    throw new Error('referenceDateOverride must be empty or a real YYYY-MM-DD date.')
  return config
}
return [{ json: queueDigestConfig($input.first().json, $now.toISO()) }];

function queueDigestSnapshot(input, config) {
  if (
    !Array.isArray(input) ||
    input.some((row) => !row || typeof row !== 'object' || Array.isArray(row))
  )
    throw new Error('Expected one object per AppStruct record.')
  const records = input.length === 1 && Object.keys(input[0]).length === 0 ? [] : input
  if (records.length >= config.limit)
    throw new Error(
      'The read reached the configured row limit. Check source completeness before reporting.'
    )
  for (const field of ['request', 'status'])
    if (records.length && !records.some((row) => Object.hasOwn(row, config.fields[field])))
      throw new Error(`No record contains the mapped ${field} column. Check field names.`)
  return {
    referenceDate: config.referenceDate,
    rows: records.map((row) =>
      Object.fromEntries(
        Object.entries(config.fields).map(([field, column]) => [
          field,
          Object.hasOwn(row, column) ? row[column] : null,
        ])
      )
    ),
  }
}
function auditServiceRequests(snapshot) {
  function isObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value)
  }
  function isDate(value) {
    if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
    const parsed = new Date(`${value}T00:00:00.000Z`)
    return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value
  }
  function text(value) {
    return typeof value === 'string' ? value.trim() : ''
  }
  if (!isObject(snapshot)) throw new Error('Expected one object with referenceDate and rows.')
  if (!isDate(snapshot.referenceDate))
    throw new Error('referenceDate must be a real YYYY-MM-DD date.')
  if (!Array.isArray(snapshot.rows))
    throw new Error('rows must be an array, including [] for an empty queue.')
  if (snapshot.rows.length > 2000)
    throw new Error('Review at most 2000 rows per snapshot; check source completeness separately.')
  const records = snapshot.rows.map((row, index) => {
    if (!isObject(row)) throw new Error(`rows[${index}] must be an object.`)
    const flags = []
    let id = ''
    if (typeof row.id === 'string') id = row.id.trim()
    else if (Number.isSafeInteger(row.id)) id = String(row.id)
    else if (row.id !== null && row.id !== undefined) flags.push('invalid_id')
    if (!id && !flags.includes('invalid_id')) flags.push('missing_id')
    const request = text(row.request)
    const status = text(row.status)
    const owner = text(row.owner)
    const dueDate = text(row.dueDate)
    if (!request) flags.push('missing_request')
    const active = status === 'new' || status === 'in_progress'
    if (!active && status !== 'done') flags.push('unknown_status')
    if (active && !owner) flags.push('unassigned')
    const hasDueDate = row.dueDate !== null && row.dueDate !== undefined && row.dueDate !== ''
    const validDueDate = isDate(dueDate)
    if (hasDueDate && !validDueDate) flags.push('invalid_due_date')
    const overdue = active && validDueDate && dueDate < snapshot.referenceDate
    if (overdue) flags.push('overdue')
    return { sourceRow: index + 1, id, request, status, owner, dueDate, overdue, flags }
  })
  const counts = new Map()
  for (const record of records)
    if (record.id) counts.set(record.id, (counts.get(record.id) || 0) + 1)
  const dataFlags = new Set([
    'missing_id',
    'invalid_id',
    'duplicate_id',
    'missing_request',
    'unknown_status',
    'invalid_due_date',
  ])
  for (const record of records) {
    if (record.id && counts.get(record.id) > 1) record.flags.push('duplicate_id')
    record.needsReview = record.flags.length > 0
    record.recommendation = record.flags.some((flag) => dataFlags.has(flag))
      ? 'Hold: correct data before automation'
      : record.flags.includes('unassigned')
        ? record.overdue
          ? 'Assign owner and review overdue request'
          : 'Assign an owner'
        : record.overdue
          ? 'Review overdue request'
          : record.status === 'done'
            ? 'Closed: no next action'
            : 'Ready for the next step'
  }
  return {
    referenceDate: snapshot.referenceDate,
    summary: {
      totalRows: records.length,
      cleanRows: records.filter((row) => !row.needsReview).length,
      reviewRows: records.filter((row) => row.needsReview).length,
      overdueRows: records.filter((row) => row.overdue).length,
      unassignedRows: records.filter((row) => row.flags.includes('unassigned')).length,
      duplicateIdRows: records.filter((row) => row.flags.includes('duplicate_id')).length,
      duplicateIds: [...counts.values()].filter((count) => count > 1).length,
    },
    records,
  }
}
function queueDigestMessage(audit, config) {
  const s = audit.summary
  return {
    sendEmail: config.notify && s.reviewRows > 0,
    fromEmail: config.fromEmail,
    toEmail: config.toEmail,
    subject: `AppStruct queue review: ${s.reviewRows} of ${s.totalRows} rows need attention`,
    text: [
      `Queue review for ${audit.referenceDate} (${config.timezone}).`,
      `Rows reviewed: ${s.totalRows}`,
      `Rows needing review: ${s.reviewRows}`,
      `Overdue active rows: ${s.overdueRows}`,
      `Unassigned active rows: ${s.unassignedRows}`,
      `Rows sharing an ID: ${s.duplicateIdRows}`,
      '',
      'Open the n8n execution to inspect flags and download the CSV report.',
      'This summary includes counts only. No request text, names or CSV attachment is emailed.',
      'No source records were changed. Repeated runs can send repeated summaries; this workflow does not deduplicate notifications.',
    ].join('\n'),
  }
}
const config = $('Validate configuration').first().json;
const snapshot = queueDigestSnapshot($input.all().map(item => item.json), config);
const audit = auditServiceRequests(snapshot);
return [{ json: { ...audit, ...queueDigestMessage(audit, config) } }];
